// v4.6.0: vendor DPA gating + override editors.
$string['settings:vendor_data_heading'] = 'بيانات المزوّدين والتكلفة';
$string['settings:vendor_data_heading_desc'] = 'عناصر التحكم في صفحة إدارة اتفاقيات معالجة البيانات (DPA) للمزوّدين الاختيارية، وفي محرّري التجاوزات اللذين يتيحان للمسؤولين إبقاء جدول المزوّدين المُرفَق وبطاقة أسعار LLM محدَّثَين دون تعديل الكود. وكلا محرّري التجاوزات بصيغة JSON؛ والقيمة الفارغة ترجع إلى الافتراضيات المضمّنة المُرفَقة مع الإضافة.';
