$string['empathy:milestones_enabled'] = 'تفعيل رسائل التأمّل عند المراحل الفارقة';
$string['empathy:milestones_enabled_desc'] = 'يُرسل رسالة بريد إلكتروني قصيرة ودافئة عندما يبلغ المتعلّم سلسلة مواظبة 7 أيام أو 30 يومًا أو يُكمل المقرر. يتطلّب المفتاح الرئيسي أعلاه إضافةً إلى موافقة كل متعلّم. وهناك حد أقصى صارم قدره رسالة واحدة لكل متعلّم كل 7 أيام عبر جميع القنوات.';
$string['empathy:memory_enabled'] = 'تفعيل ذاكرة التخصيص المُرحَّلة';
