$string['settings:prompt_budget_mode'] = 'وضع ميزانية موجّه النظام';
$string['settings:prompt_budget_mode_desc'] = 'كيفية تحديد ميزانية أحرف موجّه النظام. <strong>الاشتقاق من النموذج</strong> يحسب المساحة التي يوفّرها النموذج المُهيّأ فعليًا — نافذة سياقه مطروحًا منها الرد المحجوز وسجل المحادثة — ويستخدمها، مع حدّ أقصى حتى لا تُبيح نافذة ضخمة موجّهًا ضخمًا. ولا يسري ذلك إلا ما دامت ميزانية الأحرف أدناه على قيمتها الافتراضية 36,000: فإن غيّرت ذلك الرقم صار هو الحاكم، في الاتجاهين، لأن رقمًا كتبه مسؤول هو قرار لا تخمين. أمّا <strong>ثابت</strong> فيستخدم الرقم أدناه دائمًا. والخادم الذاتي الاستضافة ينبغي أن يضبط نافذة سياق الخلفية، ولها الأسبقية على كل ما هنا.';
$string['settings:prompt_budget_mode_auto'] = 'الاشتقاق من النموذج (موصى به)';
